MULTI_DEFS = 'function divmod(int :: a, int :: b) -> (int :: q, int :: r)\n  return a / b, mod(a, b)\nend function\n\nfunction bounds(real :: x) -> (real :: lo, real :: hi)\n  return x - 1.0, x + 1.0\nend function\n\nfunction conv(int :: n) -> (real :: a, int32 :: b, real32 :: c)\n  return n, n, n\nend function\n\nfunction early(int :: n) -> (int, int)\n  int :: i\n  do i = 1, n\n    if i * i > n then\n      return i, i * i\n    end if\n  end do\n  return 0, 0\nend function\n\nfunction noreturn(int :: n) -> (int, int)\n  if n > 0 then\n    return n, n\n  end if\nend function\n\nfunction fib2(int :: n) -> (int :: a, int :: b)\n  int :: x\n  int :: y\n  if n == 0 then\n    return 0, 1\n  end if\n  (x, y) = fib2(n - 1)\n  return y, x + y\nend function\n\nfunction sideeffect(int :: n) -> (int, int)\n  println("side", n)\n  return n, n + 1\nend function\n\nfunction strs(int :: n) -> (int, real)\n  return n, 2\nend function\n\nsubroutine outer(inout int :: acc, out int :: last)\n  int :: q\n  (q, @last) = divmod(acc, 3)\n  @acc = acc + q\nend subroutine\n\n'
