ARR_DEFS = 'function pair(real :: t) -> real[]\n  return [t, t * 2.0]\nend function\n\nfunction grid(real :: t) -> real[,]\n  return reshape([t, t, t, t, t, t], [2, 3])\nend function\n\nfunction frequencies(int :: n) -> int[]\n  int[5] :: c\n  int :: i\n  do i = 1, 5\n    c[i] = mod(i * n, 3)\n  end do\n  return c\nend function\n\nfunction widen(int[] :: v) -> real[]\n  return v\nend function\n\nfunction evens(int[] :: v) -> logical[]\n  return v > 2\nend function\n\nfunction empty() -> int[]\n  int[0] :: z\n  return z\nend function\n\nfunction early(int :: n) -> int[]\n  allocatable int[] :: r\n  int :: i\n  allocate r[n]\n  do i = 1, n\n    r[i] = i * i\n    if r[i] > 10 then\n      return r\n    end if\n  end do\n  return r\nend function\n\nfunction cube(real :: t) -> real32[]\n  return [t, t]\nend function\n\nfunction noret(int :: n) -> int[]\n  if n > 0 then\n    return [n]\n  end if\nend function\n\nfunction i32(int :: n) -> int32[]\n  return [n, n + 1]\nend function\n\nfunction chain(int :: n) -> int[]\n  int[3] :: a = [n, n, n]\n  return pair2(a)\nend function\n\nfunction pair2(int[] :: v) -> int[]\n  return v * 2\nend function\n\n'
