PROC_DEFS = 'record pt\n  real :: x = 0.0\n  real :: y = 0.0\nend record\n\nfunction square(real :: x) -> real\n  return x * x\nend function\n\nfunction cube(real :: x) -> real\n  return x * x * x\nend function\n\nfunction inv(real :: x) -> real\n  return 1.0 / x\nend function\n\nfunction integrate(function(real :: x) -> real :: f, real :: a, real :: b) -> real\n  int :: i\n  real :: s = 0.0\n  do i = 0, 9\n    s = s + f(a + (b - a) * real(i) / 10.0)\n  end do\n  return s / 10.0\nend function\n\nfunction pair(real :: t) -> real[]\n  return [t, t * 2.0]\nend function\n\nfunction total(function(real) -> real[] :: f) -> real\n  return sum(f(3.0))\nend function\n\nfunction relay(function(real) -> real[] :: g) -> real\n  return total(g)\nend function\n\nfunction bounds(real :: x) -> (real :: lo, real :: hi)\n  return x - 1.0, x + 1.0\nend function\n\nfunction spread_of(function(real :: x) -> (real :: lo, real :: hi) :: g) -> real\n  real :: lo\n  real :: hi\n  (lo, hi) = g(5.0)\n  return hi - lo\nend function\n\nsubroutine bump(inout int :: n)\n  @n = n + 1\nend subroutine\n\nsubroutine twice(subroutine(inout int) :: cb, inout int :: n)\n  call cb(@n)\n  call cb(@n)\nend subroutine\n\nsubroutine show(string :: name, real :: v)\n  println(name, v)\nend subroutine\n\nsubroutine tell(subroutine(string, real) :: s)\n  call s("alpha", 1.5)\n  call s("beta", 2.5)\nend subroutine\n\nsubroutine setr(real :: x, out real :: r)\n  @r = x * 2.0\nend subroutine\n\nsubroutine outer(subroutine(real, out real) :: f, out real :: r)\n  call f(4.0, @r)\nend subroutine\n\nfunction msize(map[string, int] :: m) -> int\n  return size(m)\nend function\n\nfunction apply(function(map[string, int]) -> int :: f, map[string, int] :: m) -> int\n  return f(m)\nend function\n\nfunction build() -> map[string, int]\n  return {"a": 1, "b": 2}\nend function\n\nfunction use_builder(function() -> map[string, int] :: g) -> int\n  map[string, int] :: m\n  m = g()\n  return size(m)\nend function\n\nfunction norm(pt :: p) -> real\n  return p.x * p.x + p.y * p.y\nend function\n\nfunction rapply(function(pt) -> real :: f, pt :: p) -> real\n  return f(p)\nend function\n\nfunction i32(int32 :: n) -> int32\n  return n + 1\nend function\n\nfunction apply32(function(int32 :: x) -> int32 :: f, int32 :: x) -> int32\n  return f(x)\nend function\n\nfunction loopf(real :: x) -> real\n  return loopf(x)\nend function\n\nfunction callit(function(real) -> real :: f) -> real\n  return f(1.0)\nend function\n\nfunction mean(real[] :: v) -> real\n  return sum(v) / real(size(v))\nend function\n\nfunction reduce(function(real[]) -> real :: f, real[] :: v) -> real\n  return f(v)\nend function\n\n'
