ENT_DEFS = 'subroutine bump(inout int :: n)\n  @n = n + 1\nend subroutine\nsubroutine fresh(out int :: n)\n  @n = 7\nend subroutine\nsubroutine two(inout int :: a, inout int :: b)\n  @a = a + b\nend subroutine\nsubroutine word(inout string :: s)\n  @s = s + "!"\nend subroutine\nsubroutine boom(inout int :: n)\n  @n = n + 1\n  println(1 / 0)\nend subroutine\nsubroutine grow(inout map[string, int] :: g, inout int :: n)\n  @g["new"] = 5\n  @n = 100\nend subroutine\nsubroutine sq(out int[] :: v)\n  int :: i\n  do i = 1, size(v)\n    @v[i] = i * i\n  end do\nend subroutine\nsubroutine dbl(inout int[] :: v)\n  @v[1] = v[1] * 2\nend subroutine\nsubroutine fr(out real :: x)\n  @x = 2.5\nend subroutine\nsubroutine nest(inout int :: n, int :: depth)\n  @n = n + 1\n  if depth > 0 then\n    call nest(@n, depth - 1)\n  end if\nend subroutine\nsubroutine swap(inout int :: a, inout int :: b)\n  int :: t\n  t = a\n  @a = b\n  @b = t\nend subroutine\nsubroutine flip(inout logical :: b)\n  @b = not b\nend subroutine\nsubroutine setl(out logical :: b)\n  @b = true\nend subroutine\nsubroutine halve(inout real :: x)\n  @x = x / 2.0\nend subroutine\nsubroutine bad(out int :: n)\n  println("never")\nend subroutine\nsubroutine viaparam(inout map[string, int] :: g)\n  call bump(@g["a"])\n  call fresh(@g["fresh"])\nend subroutine\nsubroutine tri(inout int :: a, inout int :: b, inout int :: c)\n  @a = a + 1\n  @b = b + 10\n  @c = c + 100\nend subroutine\nrecord shelf\n  map[string, int] :: stock\n  map[string, int[]] :: rows\n  map[string, string] :: names\nend record\n'
