@unittest.skipUnless(HAVE_CC, "needs a C compiler")
class ErrorTests(unittest.TestCase):
    def test_real32_errors_and_ieee_answers_are_the_interpreters(self):
        for name, body in REAL32_CASES.items():
            with self.subTest(name):
                done = same_as_interpreter(self, prog(body))
                self.assertEqual(done.returncode, 1, name)
                self.assertIn("error: line", done.stderr)
            with self.subTest(name + " (use ieee)"):
                same_as_interpreter(self, "use ieee\n" + prog(body))

    def test_out_parameter_mistakes_are_the_interpreters(self):
        for name, defs in OUT_DEFS.items():
            with self.subTest(name):
                arg, decl = ("a", "  int[2] :: a = [1, 2]") if "array" in name else ("n", "  int :: n = 3")
                done = same_as_interpreter(self, prog(f"{decl}\n  call s(@{arg}{', 0' if 'never' in name else ''})", defs))
                self.assertEqual(done.returncode, 1, name)
                self.assertIn("error: line", done.stderr)

    def test_math_function_errors_and_ieee_answers_are_the_interpreters(self):
        for name, body in MATH_CASES.items():
            with self.subTest(name):
                same_as_interpreter(self, prog(body))
            if not name.startswith("mod"):                       # (modulo is not compiled in a file that says `use ieee`)
                with self.subTest(name + " (use ieee)"):
                    same_as_interpreter(self, "use ieee\n" + prog(body))

    def test_records_behave_as_in_the_interpreter(self):
        for defs, cases in ((RECORD_DEFS, RECORD_CASES), (RECORD_DEFS_2, RECORD_CASES_2), (RECORD_DEFS_3, RECORD_CASES_3),
                            (RECORD_DEFS_4, RECORD_CASES_4),
                            (RECORD_DEFS_5, RECORD_CASES_5),
                            (IFACE_DEFS, IFACE_CASES),
                            (SELECT_DEFS, SELECT_CASES),
                            (CASE_DEFS, CASE_CASES),
                            (FIELD_DEFS, FIELD_CASES),
                            (OPT_DEFS, OPT_CASES),
                            (MODULE_DEFS, MODULE_CASES),
                            (STRING_DEFS, STRING_CASES), ("", FORMAT_CASES)):
            for name, body in cases.items():
                with self.subTest(name):
                    built = boreas("emit-c", self.write(prog(body, defs)))
                    if built.returncode != 0:                       # not compiled: refused as a whole, never partial
                        self.assertIn("not supported by the compiler yet", built.stderr)
                        continue
                    same_as_interpreter(self, prog(body, defs))
                    same_as_interpreter(self, "use ieee\n" + prog(body, defs))

    def write(self, source):
        handle, path = tempfile.mkstemp(suffix=".bor")
        self.addCleanup(os.remove, path)
        with os.fdopen(handle, "w") as f:
            f.write(source)
        return path

    def test_more_built_in_functions_are_compiled_and_match_the_interpreter(self):
        """Bit functions, to_integer / to_real / to_logical, nan / infinity / isnan, scan / verify / replace / adjustl / iachar,
        norm2, lbound / ubound, findloc, maxloc of a matrix, pack and spread: every one of these is compiled (not refused)."""
        for name, body in FUNC_CASES.items():
            with self.subTest(name):
                source = prog(body, FUNC_DEFS)
                built = boreas("emit-c", self.write(source))
                self.assertEqual(built.returncode, 0, built.stderr[-300:])
                same_as_interpreter(self, source)
        for name in ("nan1_basic", "nan1_arith", "nan1_formats", "norm1_nan", "norm1_inf", "loc1_nan", "special_cos_inf",
                     "special_sin_neginf", "special_real32_inf", "special_mod_inf"):
            with self.subTest(name + " (use ieee)"):
                same_as_interpreter(self, "use ieee\n" + prog(FUNC_CASES[name]))

    def test_maps_and_sets_are_compiled_and_match_the_interpreter(self):
        """Maps and sets of whole numbers and text (locals and parameters): the order the entries were added in, copies, the
        errors, `do ... in`, literals, `==`, and the sizes that make the table grow: all compiled, none refused."""
        for name, body in MAP_CASES.items():
            with self.subTest(name):
                source = prog(body, MAP_DEFS)
                built = boreas("emit-c", self.write(source))
                self.assertEqual(built.returncode, 0, built.stderr[-300:])
                same_as_interpreter(self, source)

    def test_maps_and_sets_as_record_fields_are_compiled_and_match_the_interpreter(self):
        """A record can hold maps and sets: they start empty, are copied with the record, and work like variables."""
        for name, body in RFIELD_CASES.items():
            with self.subTest(name):
                source = prog(body, RFIELD_DEFS)
                built = boreas("emit-c", self.write(source))
                self.assertEqual(built.returncode, 0, built.stderr[-300:])
                same_as_interpreter(self, source)

    def test_maps_of_sets_and_arrays_and_map_results_are_compiled_and_match_the_interpreter(self):
        """Sets and arrays that live in a map (changed in place, copied in and out), maps and sets given back by functions."""
        for name, body in NEST_CASES.items():
            with self.subTest(name):
                source = prog(body, NEST_DEFS)
                built = boreas("emit-c", self.write(source))
                self.assertEqual(built.returncode, 0, built.stderr[-300:])
                same_as_interpreter(self, source)

    def test_functions_with_several_results_are_compiled_and_match_the_interpreter(self):
        """`(q, r) = divmod(a, b)`: results of numbers and logicals, `_`, targets of any kind, conversions, errors."""
        for name, body in MULTI_CASES.items():
            with self.subTest(name):
                source = prog(body, MULTI_DEFS)
                built = boreas("emit-c", self.write(source))
                self.assertEqual(built.returncode, 0, built.stderr[-300:])
                same_as_interpreter(self, source)

    def test_functions_that_return_arrays_are_compiled_and_match_the_interpreter(self):
        """`-> real[]`, `-> real[,]`, `-> int[]`...: the array a function gives back, its conversions and errors."""
        for name, body in ARR_CASES.items():
            with self.subTest(name):
                source = prog(body, ARR_DEFS)
                built = boreas("emit-c", self.write(source))
                self.assertEqual(built.returncode, 0, built.stderr[-300:])
                same_as_interpreter(self, source)

    def test_procedure_parameters_are_compiled_and_match_the_interpreter(self):
        """Callbacks: functions and subroutines passed by name, with results of numbers, arrays, several values, maps and
        records, passed on, called many times, and the errors inside them."""
        for name, body in PROC_CASES.items():
            with self.subTest(name):
                source = prog(body, PROC_DEFS)
                built = boreas("emit-c", self.write(source))
                self.assertEqual(built.returncode, 0, built.stderr[-300:])
                same_as_interpreter(self, source)

    def test_bessel_functions_exists_and_the_command_line_are_compiled_and_match_the_interpreter(self):
        """bessel_j0 ... bessel_yn (the C library's, with the interpreter's errors), exists, argument_count, argument."""
        for name, body in SYS_CASES.items():
            with self.subTest(name):
                source = prog(body)
                built = boreas("emit-c", self.write(source))
                self.assertEqual(built.returncode, 0, built.stderr[-300:])
                same_as_interpreter(self, source)

    def test_complex_numbers_are_compiled_and_match_the_interpreter(self):
        """complex values (scalars, arrays, fields, parameters, results) with Python's own arithmetic, abs, real, aimag, conjg, cmplx,
        sum, product, dot_product, matmul, transpose, printing, and the errors."""
        for name, body in CX_CASES.items():
            with self.subTest(name):
                source = prog(body, CX_DEFS)
                built = boreas("emit-c", self.write(source))
                self.assertEqual(built.returncode, 0, built.stderr[-300:])
                same_as_interpreter(self, source)

    def test_the_complex_functions_are_compiled_and_match_the_interpreter(self):
        """sqrt, exp, log, log10, the trigonometric and hyperbolic functions and their inverses of a complex number or array,
        with their special values and the errors (which are the interpreter's with or without `use ieee`)."""
        for name, body in CM_CASES.items():
            for ieee in (False, True):
                with self.subTest(name, ieee=ieee):
                    source = ("use ieee\n" if ieee else "") + prog(body)
                    built = boreas("emit-c", self.write(source))
                    self.assertEqual(built.returncode, 0, built.stderr[-300:])
                    same_as_interpreter(self, source)

    def test_map_entries_passed_as_out_or_inout_are_compiled_and_match_the_interpreter(self):
        """`call bump(@m["a"])`, `call fresh(@m["new"])`, entries of an array or record-field map, an element `@m["k"][2]`, two entries
        of one map (equal keys are the interpreter's aliasing error), and the missing-key and never-assigned errors."""
        for name, body in ENT_CASES.items():
            with self.subTest(name):
                source = prog(body, ENT_DEFS)
                built = boreas("emit-c", self.write(source))
                self.assertEqual(built.returncode, 0, built.stderr[-300:])
                same_as_interpreter(self, source)

    def test_where_is_compiled_and_matches_the_interpreter(self):
        """`where mask ... elsewhere ... end where`: masks, nesting, sections, a mask that changes as the body runs, and the error
        messages and lines (an operator's error names the `where`, a subscript's or a math function's its own line)."""
        for name, body in WHERE_CASES.items():
            for ieee in (False, True):
                with self.subTest(name, ieee=ieee):
                    source = ("use ieee\n" if ieee else "") + prog(body, WHERE_DEFS)
                    built = boreas("emit-c", self.write(source))
                    self.assertEqual(built.returncode, 0, built.stderr[-300:])
